package dev.themurft.thesmp;

import java.io.File;
import java.io.IOException;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.UUID;
import org.bukkit.Bukkit;
import org.bukkit.Location;
import org.bukkit.Material;
import org.bukkit.Statistic;
import org.bukkit.configuration.ConfigurationSection;
import org.bukkit.configuration.file.YamlConfiguration;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.Listener;
import org.bukkit.event.entity.PlayerDeathEvent;
import org.bukkit.event.player.AsyncPlayerChatEvent;
import org.bukkit.event.player.PlayerTeleportEvent;
import org.bukkit.inventory.Inventory;
import org.bukkit.inventory.InventoryHolder;

final class SmpExpansion implements Listener {
    record WarpsHolder(Map<Integer,String> slots) implements InventoryHolder { public Inventory getInventory(){return null;} }
    record RewardsHolder() implements InventoryHolder { public Inventory getInventory(){return null;} }
    record QuestsHolder(List<String> ids) implements InventoryHolder { public Inventory getInventory(){return null;} }
    private final TheSmp plugin;
    private final File file;
    private final YamlConfiguration data;

    SmpExpansion(TheSmp plugin){this.plugin=plugin;file=new File(plugin.getDataFolder(),"expansion.yml");data=YamlConfiguration.loadConfiguration(file);Bukkit.getPluginManager().registerEvents(this,plugin);}
    private void msg(Player p,String key,String... replacements){plugin.message(p,"expansion."+key,replacements);}
    private String tr(Player p,String key,String... replacements){return plugin.tr(p,"expansion."+key,replacements);}
    void save(){try{data.save(file);}catch(IOException e){plugin.getLogger().severe("Could not save expansion.yml: "+e.getMessage());}}
    boolean handles(String command){return List.of("warp","warps","setwarp","delwarp","back","ignore","unignore","ignorelist","warn","warnings","mute","unmute","history","profile","daily","rewards","quests").contains(command);}
    boolean command(Player p,String command,String[] args){return switch(command){case "warp"->warp(p,args);case "warps"->{if(p.hasPermission("thesmp.warps"))openWarps(p);else plugin.message(p,"no-permission");yield true;}case "setwarp"->setWarp(p,args);case "delwarp"->deleteWarp(p,args);case "back"->back(p);case "ignore"->ignore(p,args,true);case "unignore"->ignore(p,args,false);case "ignorelist"->{ignoreList(p);yield true;}case "warn"->warn(p,args);case "warnings"->warnings(p,args);case "mute"->mute(p,args);case "unmute"->unmute(p,args);case "history"->history(p,args);case "profile"->profile(p,args);case "daily"->claimDaily(p);case "rewards"->{if(p.hasPermission("thesmp.daily"))openRewards(p);else plugin.message(p,"no-permission");yield true;}case "quests"->{openQuests(p);yield true;}default->false;};}
    boolean ignored(UUID owner,UUID target){return data.getStringList("ignored."+owner).contains(target.toString());}
    @SuppressWarnings({"unchecked","rawtypes"})
    boolean charge(Player p,String action){double amount=plugin.getConfig().getDouble("economy.costs."+action,0);if(amount<=0)return true;try{Class<?> type=Class.forName("net.milkbowl.vault.economy.Economy");Object registration=Bukkit.getServicesManager().getRegistration((Class)type);if(registration==null){msg(p,"economy.unavailable");return false;}Object economy=registration.getClass().getMethod("getProvider").invoke(registration);boolean has=(boolean)type.getMethod("has",org.bukkit.OfflinePlayer.class,double.class).invoke(economy,p,amount);if(!has){msg(p,"economy.need","%amount%",String.valueOf(amount));return false;}type.getMethod("withdrawPlayer",org.bukkit.OfflinePlayer.class,double.class).invoke(economy,p,amount);msg(p,"economy.paid","%amount%",String.valueOf(amount));return true;}catch(Exception e){msg(p,"economy.vault-unavailable");return false;}}
    @SuppressWarnings({"unchecked","rawtypes"}) boolean chargeAmount(Player p,double amount){if(!Double.isFinite(amount)||amount<=0)return false;try{Class<?> type=Class.forName("net.milkbowl.vault.economy.Economy");Object reg=Bukkit.getServicesManager().getRegistration((Class)type);if(reg==null)return false;Object economy=reg.getClass().getMethod("getProvider").invoke(reg);if(!(boolean)type.getMethod("has",org.bukkit.OfflinePlayer.class,double.class).invoke(economy,p,amount)){msg(p,"economy.not-enough");return false;}type.getMethod("withdrawPlayer",org.bukkit.OfflinePlayer.class,double.class).invoke(economy,p,amount);return true;}catch(Exception e){msg(p,"economy.vault-unavailable");return false;}}
    @SuppressWarnings({"unchecked","rawtypes"}) boolean credit(Player p,double amount){if(!Double.isFinite(amount)||amount<=0)return false;try{Class<?> type=Class.forName("net.milkbowl.vault.economy.Economy");Object reg=Bukkit.getServicesManager().getRegistration((Class)type);if(reg==null)return false;Object economy=reg.getClass().getMethod("getProvider").invoke(reg);type.getMethod("depositPlayer",org.bukkit.OfflinePlayer.class,double.class).invoke(economy,p,amount);return true;}catch(Exception e){msg(p,"economy.vault-unavailable");return false;}}
    private boolean setWarp(Player p,String[] args){if(!p.hasPermission("thesmp.warps.admin")){plugin.message(p,"no-permission");return true;}if(args.length==0){msg(p,"warps.set-usage");return true;}if(!args[0].matches("[A-Za-z0-9]+")){plugin.message(p,"safety.invalid-warp");return true;}String name=clean(args[0]);data.set("warps."+name+".location",p.getLocation());data.set("warps."+name+".display",args[0]);save();msg(p,"warps.created","%warp%",name);return true;}
    private boolean deleteWarp(Player p,String[] args){if(!p.hasPermission("thesmp.warps.admin")){plugin.message(p,"no-permission");return true;}if(args.length==0){msg(p,"warps.delete-usage");return true;}String name=clean(args[0]);if(!data.contains("warps."+name)){msg(p,"warps.not-found");return true;}data.set("warps."+name,null);save();msg(p,"warps.deleted");return true;}
    private boolean warp(Player p,String[] args){if(!p.hasPermission("thesmp.warps")){plugin.message(p,"no-permission");return true;}if(args.length==0){openWarps(p);return true;}String name=clean(args[0]);if(!p.hasPermission("thesmp.warp."+name)&&!p.hasPermission("thesmp.warp.*")){plugin.message(p,"no-permission");return true;}Location location=data.getLocation("warps."+name+".location");if(location==null||location.getWorld()==null){msg(p,"warps.not-found");return true;}Location previous=p.getLocation();p.teleportAsync(location).thenAccept(success->Bukkit.getScheduler().runTask(plugin,()->{if(!success){plugin.message(p,"teleport-failed");return;}if(!charge(p,"warp")){p.teleportAsync(previous);return;}remember(p,previous);msg(p,"warps.teleported","%warp%",name);}));return true;}
    void openWarps(Player p){
        ConfigurationSection root=data.getConfigurationSection("warps");List<String> names=root==null?List.of():new ArrayList<>(root.getKeys(false));YamlConfiguration menu=plugin.warpMenuConfig();
        int requested=menu.getInt("size",Math.max(9,((names.size()+8)/9)*9));int size=Math.max(1,Math.min(6,(requested+8)/9))*9;
        String title=replaceWarpPlaceholders(menu.getString("title",tr(p,"warps.title")),null,"",names.size());Map<Integer,String> slots=new LinkedHashMap<>();Set<Integer> used=new HashSet<>();
        for(String id:names){String base="warps."+id;int slot=menu.getInt(base+".slot",-1);if(slot<0||slot>=size||used.contains(slot)){slot=0;while(slot<size&&used.contains(slot))slot++;}if(slot>=size)continue;used.add(slot);slots.put(slot,id);}
        Inventory inv=Bukkit.createInventory(new WarpsHolder(slots),size,plugin.color(title));
        if(menu.getBoolean("fill-empty-slots",true)){Material filler=material(menu.getString("filler.material","BLACK_STAINED_GLASS_PANE"),Material.BLACK_STAINED_GLASS_PANE);String fillerName=menu.getString("filler.name"," ");for(int i=0;i<size;i++)inv.setItem(i,plugin.item(filler,fillerName,List.of()));}
        for(Map.Entry<Integer,String> entry:slots.entrySet()){String id=entry.getValue(),base="warps."+id,defaults="default-item";Location location=data.getLocation("warps."+id+".location");String display=data.getString("warps."+id+".display",id);Material icon=material(menu.getString(base+".material",menu.getString(defaults+".material","ENDER_PEARL")),Material.ENDER_PEARL);String itemName=replaceWarpPlaceholders(menu.getString(base+".name",menu.getString(defaults+".name","&b%warp%")),location,display,names.size());List<String> lore=menu.isList(base+".lore")?menu.getStringList(base+".lore"):menu.getStringList(defaults+".lore");if(lore.isEmpty())lore=List.of(tr(p,"warps.click"));List<String> rendered=lore.stream().map(line->replaceWarpPlaceholders(line,location,display,names.size())).toList();inv.setItem(entry.getKey(),plugin.item(icon,itemName,rendered));}
        p.openInventory(inv);
    }
    void clickWarp(Player p,WarpsHolder holder,int slot){String warp=holder.slots.get(slot);if(warp==null)return;p.closeInventory();p.performCommand("warp "+warp);}
    private Material material(String value,Material fallback){try{Material material=Material.valueOf(value.toUpperCase(Locale.ROOT));return material.isItem()&&!material.isAir()?material:fallback;}catch(Exception ignored){return fallback;}}
    private String replaceWarpPlaceholders(String value,Location location,String warp,int count){String result=value.replace("%warp%",warp).replace("%count%",String.valueOf(count));if(location!=null)result=result.replace("%world%",location.getWorld()==null?"unknown":location.getWorld().getName()).replace("%x%",String.valueOf(location.getBlockX())).replace("%y%",String.valueOf(location.getBlockY())).replace("%z%",String.valueOf(location.getBlockZ()));return result;}
    private boolean back(Player p){if(!p.hasPermission("thesmp.back")){plugin.message(p,"no-permission");return true;}Location location=data.getLocation("back."+p.getUniqueId());if(location==null||location.getWorld()==null){msg(p,"back.none");return true;}Location current=p.getLocation();p.teleportAsync(location).thenAccept(success->Bukkit.getScheduler().runTask(plugin,()->{if(success){remember(p,current);msg(p,"back.success");}else plugin.message(p,"teleport-failed");}));return true;}
    private void remember(Player p,Location location){data.set("back."+p.getUniqueId(),location);save();}
    @EventHandler public void onDeath(PlayerDeathEvent e){remember(e.getEntity(),e.getEntity().getLocation());}
    @EventHandler public void onTeleport(PlayerTeleportEvent e){if(e.getCause()!=PlayerTeleportEvent.TeleportCause.PLUGIN&&e.getCause()!=PlayerTeleportEvent.TeleportCause.COMMAND)remember(e.getPlayer(),e.getFrom());}
    private boolean ignore(Player p,String[] args,boolean add){if(!p.hasPermission("thesmp.ignore")){plugin.message(p,"no-permission");return true;}if(args.length==0){msg(p,add?"ignore.usage":"ignore.unusage");return true;}var target=Bukkit.getOfflinePlayer(args[0]);if(target.getUniqueId().equals(p.getUniqueId())){msg(p,"ignore.self");return true;}String path="ignored."+p.getUniqueId();List<String> list=new ArrayList<>(data.getStringList(path));if(add&&!list.contains(target.getUniqueId().toString()))list.add(target.getUniqueId().toString());if(!add)list.remove(target.getUniqueId().toString());data.set(path,list);save();msg(p,add?"ignore.added":"ignore.removed","%player%",args[0]);return true;}
    private void ignoreList(Player p){List<String> names=data.getStringList("ignored."+p.getUniqueId()).stream().map(x->{try{var op=Bukkit.getOfflinePlayer(UUID.fromString(x));return op.getName()==null?x.substring(0,8):op.getName();}catch(Exception e){return x;}}).toList();msg(p,"ignore.list","%players%",names.isEmpty()?tr(p,"ignore.none"):String.join(", ",names));}
    private boolean warn(Player staff,String[] args){if(!staff.hasPermission("thesmp.moderation.warn")){plugin.message(staff,"no-permission");return true;}if(args.length<2){msg(staff,"moderation.warn-usage");return true;}var target=Bukkit.getOfflinePlayer(args[0]);String reason=String.join(" ",java.util.Arrays.copyOfRange(args,1,args.length));String path="moderation.warnings."+target.getUniqueId();List<String> list=new ArrayList<>(data.getStringList(path));list.add(System.currentTimeMillis()+"|"+staff.getName()+"|"+reason);data.set(path,list);save();msg(staff,"moderation.warned","%player%",args[0]);Player online=target.getPlayer();if(online!=null)msg(online,"moderation.warning","%reason%",reason);return true;}
    private boolean warnings(Player viewer,String[] args){UUID id;if(args.length>0&&viewer.hasPermission("thesmp.moderation.view"))id=Bukkit.getOfflinePlayer(args[0]).getUniqueId();else id=viewer.getUniqueId();List<String> list=data.getStringList("moderation.warnings."+id);viewer.sendMessage(tr(viewer,"moderation.warnings-title"));if(list.isEmpty())msg(viewer,"moderation.no-warnings");else for(int i=0;i<list.size();i++){String[] part=list.get(i).split("\\|",3);viewer.sendMessage(tr(viewer,"moderation.warning-entry","%number%",String.valueOf(i+1),"%reason%",part.length>2?part[2]:list.get(i),"%staff%",part.length>1?part[1]:tr(viewer,"moderation.unknown")));}return true;}
    private boolean mute(Player staff,String[] args){if(!staff.hasPermission("thesmp.moderation.mute")){plugin.message(staff,"no-permission");return true;}if(args.length<2){msg(staff,"moderation.mute-usage");return true;}long minutes,max=plugin.getConfig().getLong("moderation.max-mute-minutes",525600);try{minutes=Long.parseLong(args[1]);if(minutes<1||minutes>max||minutes>Long.MAX_VALUE/60000)throw new NumberFormatException();}catch(NumberFormatException e){plugin.message(staff,"safety.invalid-mute","%max%",String.valueOf(max));return true;}var target=Bukkit.getOfflinePlayer(args[0]);String reason=args.length>2?String.join(" ",java.util.Arrays.copyOfRange(args,2,args.length)):tr(staff,"moderation.default-reason");long until;try{until=Math.addExact(System.currentTimeMillis(),Math.multiplyExact(minutes,60000));}catch(ArithmeticException e){plugin.message(staff,"safety.invalid-mute","%max%",String.valueOf(max));return true;}data.set("moderation.mutes."+target.getUniqueId()+".until",until);data.set("moderation.mutes."+target.getUniqueId()+".reason",reason);data.set("moderation.mutes."+target.getUniqueId()+".staff",staff.getName());save();msg(staff,"moderation.muted","%player%",args[0],"%minutes%",String.valueOf(minutes));Player online=target.getPlayer();if(online!=null)msg(online,"moderation.muted-target","%reason%",reason);return true;}
    private boolean unmute(Player staff,String[] args){if(!staff.hasPermission("thesmp.moderation.mute")){plugin.message(staff,"no-permission");return true;}if(args.length==0){msg(staff,"moderation.unmute-usage");return true;}var target=Bukkit.getOfflinePlayer(args[0]);data.set("moderation.mutes."+target.getUniqueId(),null);save();msg(staff,"moderation.unmuted","%player%",args[0]);Player online=target.getPlayer();if(online!=null)plugin.message(online,"safety.unmuted-target");return true;}
    private boolean history(Player staff,String[] args){if(!staff.hasPermission("thesmp.moderation.view")){plugin.message(staff,"no-permission");return true;}if(args.length==0){msg(staff,"moderation.history-usage");return true;}UUID id=Bukkit.getOfflinePlayer(args[0]).getUniqueId();warnings(staff,args);long until=data.getLong("moderation.mutes."+id+".until",0);if(until>System.currentTimeMillis())msg(staff,"moderation.active-mute","%reason%",data.getString("moderation.mutes."+id+".reason",tr(staff,"moderation.default-reason")));else msg(staff,"moderation.no-active-mute");return true;}
    @EventHandler public void onChat(AsyncPlayerChatEvent e){String path="moderation.mutes."+e.getPlayer().getUniqueId();long until;String reason;synchronized(data){until=data.getLong(path+".until",0);reason=data.getString(path+".reason",tr(e.getPlayer(),"moderation.default-reason"));}long now=System.currentTimeMillis();if(until>now){e.setCancelled(true);long remaining=(until-now+59999)/60000;Bukkit.getScheduler().runTask(plugin,()->msg(e.getPlayer(),"moderation.muted-chat","%minutes%",String.valueOf(remaining),"%reason%",reason));}else if(until>0)Bukkit.getScheduler().runTask(plugin,()->{if(data.getLong(path+".until",0)>0&&data.getLong(path+".until",0)<=System.currentTimeMillis()){data.set(path,null);save();plugin.message(e.getPlayer(),"safety.mute-expired");}});}
    private boolean profile(Player viewer,String[] args){if(!viewer.hasPermission("thesmp.profile")){plugin.message(viewer,"no-permission");return true;}var target=args.length==0?viewer:Bukkit.getOfflinePlayer(args[0]);if(!target.equals(viewer)&&!viewer.hasPermission("thesmp.profile.others")){plugin.message(viewer,"no-permission");return true;}String name=target.getName()==null?(args.length==0?viewer.getName():args[0]):target.getName();long ticks=target.getStatistic(Statistic.PLAY_ONE_MINUTE);long hours=ticks/20/3600;viewer.sendMessage(tr(viewer,"profile.title","%player%",name));msg(viewer,"profile.status","%status%",tr(viewer,target.isOnline()?"profile.online":"profile.offline"));msg(viewer,"profile.playtime","%hours%",String.valueOf(hours));msg(viewer,"profile.stats","%players%",String.valueOf(target.getStatistic(Statistic.PLAYER_KILLS)),"%mobs%",String.valueOf(target.getStatistic(Statistic.MOB_KILLS)),"%deaths%",String.valueOf(target.getStatistic(Statistic.DEATHS)));msg(viewer,"profile.friends","%count%",String.valueOf(plugin.friendCount(target.getUniqueId())));msg(viewer,"profile.clan","%clan%",plugin.clanProfile(target.getUniqueId()));msg(viewer,"profile.last-seen","%time%",target.isOnline()?tr(viewer,"profile.now"):new java.util.Date(target.getLastSeen()).toString());return true;}
    void openRewards(Player p){long now=java.time.LocalDate.now(java.time.ZoneOffset.UTC).toEpochDay();long last=data.getLong("daily."+p.getUniqueId()+".day",-1);int streak=data.getInt("daily."+p.getUniqueId()+".streak",0);Inventory inv=Bukkit.createInventory(new RewardsHolder(),27,tr(p,"daily.title"));for(int i=0;i<27;i++)inv.setItem(i,plugin.item(Material.GRAY_STAINED_GLASS_PANE," ",null));inv.setItem(13,plugin.item(last==now?Material.MINECART:Material.CHEST,tr(p,last==now?"daily.claimed-name":"daily.claim-name"),List.of(tr(p,"daily.streak","%streak%",String.valueOf(streak)),tr(p,last==now?"daily.tomorrow":"daily.click"))));p.openInventory(inv);}
    void clickRewards(Player p,int slot){if(slot==13){p.closeInventory();claimDaily(p);}}
    private boolean claimDaily(Player p){if(!p.hasPermission("thesmp.daily")){plugin.message(p,"no-permission");return true;}long now=java.time.LocalDate.now(java.time.ZoneOffset.UTC).toEpochDay();String base="daily."+p.getUniqueId();long last=data.getLong(base+".day",-1);if(last==now){msg(p,"daily.already");return true;}int streak=last==now-1?data.getInt(base+".streak",0)+1:1;data.set(base+".day",now);data.set(base+".streak",streak);save();for(String command:plugin.getConfig().getStringList("daily-rewards.commands"))Bukkit.dispatchCommand(Bukkit.getConsoleSender(),command.replace("%player%",p.getName()).replace("%streak%",String.valueOf(streak)));int every=Math.max(1,plugin.getConfig().getInt("daily-rewards.bonus-every",7));if(streak%every==0)for(String command:plugin.getConfig().getStringList("daily-rewards.bonus-commands"))Bukkit.dispatchCommand(Bukkit.getConsoleSender(),command.replace("%player%",p.getName()).replace("%streak%",String.valueOf(streak)));msg(p,"daily.success","%streak%",String.valueOf(streak));return true;}
    void openQuests(Player p){if(!p.hasPermission("thesmp.quests")){plugin.message(p,"no-permission");return;}ConfigurationSection root=plugin.getConfig().getConfigurationSection("quests");List<String> ids=root==null?List.of():new ArrayList<>(root.getKeys(false));Inventory inv=Bukkit.createInventory(new QuestsHolder(ids),Math.max(9,Math.min(54,((ids.size()+8)/9)*9)),tr(p,"quests.title"));refreshQuests(p,inv,new QuestsHolder(ids));p.openInventory(inv);}
    void refreshQuests(Player p,Inventory inv,QuestsHolder holder){for(int i=0;i<holder.ids.size()&&i<inv.getSize();i++){String id=holder.ids.get(i),base="quests."+id;resetQuest(p,id);long progress=questProgress(p,id);long target=Math.max(1,plugin.getConfig().getLong(base+".target",1));boolean claimed=data.getBoolean("quest-progress."+p.getUniqueId()+"."+id+".claimed",false);Material material=claimed?Material.MINECART:progress>=target?Material.CHEST:Material.PAPER;inv.setItem(i,plugin.item(material,plugin.getConfig().getString(base+".name","&b"+id),List.of(tr(p,"quests.period","%period%",plugin.getConfig().getString(base+".period","daily")),tr(p,"quests.progress","%progress%",String.valueOf(Math.min(progress,target)),"%target%",String.valueOf(target)),tr(p,claimed?"quests.claimed":progress>=target?"quests.claim":"quests.keep-playing"))));}}
    void clickQuest(Player p,QuestsHolder holder,int slot){if(slot<0||slot>=holder.ids.size())return;String id=holder.ids.get(slot);resetQuest(p,id);long target=Math.max(1,plugin.getConfig().getLong("quests."+id+".target",1));String path="quest-progress."+p.getUniqueId()+"."+id;if(data.getBoolean(path+".claimed",false)||questProgress(p,id)<target)return;data.set(path+".claimed",true);save();for(String command:plugin.getConfig().getStringList("quests."+id+".commands"))Bukkit.dispatchCommand(Bukkit.getConsoleSender(),command.replace("%player%",p.getName()));p.closeInventory();msg(p,"quests.reward","%quest%",id);}
    private void resetQuest(Player p,String id){String period=plugin.getConfig().getString("quests."+id+".period","daily");long key=period.equalsIgnoreCase("weekly")?java.time.LocalDate.now(java.time.ZoneOffset.UTC).toEpochDay()/7:java.time.LocalDate.now(java.time.ZoneOffset.UTC).toEpochDay();String path="quest-progress."+p.getUniqueId()+"."+id;if(data.getLong(path+".period",Long.MIN_VALUE)!=key){data.set(path+".period",key);data.set(path+".baseline",questStatistic(p,plugin.getConfig().getString("quests."+id+".type","PLAYTIME")));data.set(path+".claimed",false);save();}}
    private long questProgress(Player p,String id){String path="quest-progress."+p.getUniqueId()+"."+id;return Math.max(0,questStatistic(p,plugin.getConfig().getString("quests."+id+".type","PLAYTIME"))-data.getLong(path+".baseline",0));}
    private long questStatistic(Player p,String type){return switch(type.toUpperCase(Locale.ROOT)){case "MOB_KILLS"->p.getStatistic(Statistic.MOB_KILLS);case "PLAYER_KILLS"->p.getStatistic(Statistic.PLAYER_KILLS);case "DEATHS"->p.getStatistic(Statistic.DEATHS);default->p.getStatistic(Statistic.PLAY_ONE_MINUTE)/20/60;};}
    private String clean(String value){return value.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9_-]","");}
}
